{
  "name": "ke_list_search_notify",
  "confidence": "medium",
  "docstring": "Processes a kernel list-search completion by updating the matched or pending entry state and sending the associated kernel event messages.",
  "subsystem": "ke",
  "var_renames": {
    "v1": "ctx",
    "v2": "current_entry",
    "v3": "result_entry",
    "v4": "entry_status_msg",
    "v5": "event_msg"
  },
  "struct_hints": [
    {
      "offset": 4,
      "meaning": "context scalar parameter used as the event-message payload"
    },
    {
      "offset": 16,
      "meaning": "entry state byte (2=pending/scheduled, 4=matched/complete)"
    },
    {
      "offset": 24,
      "meaning": "entry type or status byte copied into kernel message 69"
    },
    {
      "offset": 40,
      "meaning": "context current/target entry pointer"
    },
    {
      "offset": 44,
      "meaning": "context result/pending entry pointer"
    }
  ]
}
